import json
from collections import Counter

def transform(grid):
    g=[r[:] for r in grid]; h=len(g); w=len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    def nnon(row): return sum(1 for x in row if x!=bg)
    pat=[i for i,r in enumerate(g) if 0<nnon(r)<w]
    if not pat: return g
    blocks=[]; cur=[pat[0]]
    for i in pat[1:]:
        if i==cur[-1]+1: cur.append(i)
        else: blocks.append(cur); cur=[i]
    blocks.append(cur)
    if len(blocks)<2: return g
    def score(b): return sum(nnon(g[i]) for i in b)
    tmpl=max(blocks,key=score)
    trows=[g[i] for i in tmpl]
    for b in blocks:
        if b is tmpl or len(b)!=len(tmpl): continue
        for ri,i in enumerate(b):
            for j in range(w):
                if g[i][j]==bg and trows[ri][j]!=bg: g[i][j]=1
    return g

